package com.classvoice.controller; import com.classvoice.dao.*; import com.classvoice.model.*; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/teacher/topic/add") public class AddTopicServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{long lid=WebUtil.longParam(r,"lectureId");String name=WebUtil.trim(r.getParameter("topicName")),desc=WebUtil.trim(r.getParameter("topicDescription"));try{User u=(User)r.getSession().getAttribute("user");LectureDAO ld=new LectureDAO();if(lid<1||!ld.belongsToTeacher(lid,u.getUserId())){p.sendError(404);return;}if(name.length()<2||name.length()>150||desc.length()>300){r.getSession().setAttribute("flashError","Topic name/description is invalid.");}else{Topic t=new Topic();t.setLectureId(lid);t.setTopicName(name);t.setDescription(desc);new TopicDAO().create(t);r.getSession().setAttribute("flash","Topic added.");}p.sendRedirect(r.getContextPath()+"/teacher/topics?lectureId="+lid);}catch(Exception e){throw new ServletException(e);}}}
